 document.addEventListener("finanzasoss:v41-open-saved-review",async event=>{
  if(busy)return;
  busy=true;
  invalidate();
  feedback.textContent="Abriendo revisi\xF3n guardada\u2026";
  reveal();
  try{
   const data=await draftRequest("?id="+encodeURIComponent(event.detail.id));
   current={input:data.input,result:data.result,draftId:data.id};
   renderReview();
   const match=list.querySelector(".v41-decision-card[data-possible-duplicate]");
   if(event.detail.duplicate&&match)match.scrollIntoView({block:"center"});
   if(!data.result.rows.length)feedback.textContent="Todas las filas ya se decidieron. Puedes descartar este borrador.";
  }catch(error){feedback.textContent=error.message;}
  finally{busy=false; evaluate();}
 });
 draftButton.addEventListener("click",async()=>{
  if(busy||!current)return;
  const pending=current;
  busy=true;draftButton.disabled=true;evaluate();
  try{
   const data=await draftRequest("",pending.input);
   if(current!==pending)return;
   current.draftId=data.id;
   draftButton.hidden=true;discardButton.hidden=false;
   feedback.textContent=data.pending?"Filas guardadas. Retoma la revisi\xF3n desde Qwen. Las decisiones elegidas se guardan al confirmarlas.":"Estas filas ya quedaron decididas en el historial.";
  }catch(error){feedback.textContent=error.message;}
  finally{busy=false;draftButton.disabled=false;evaluate();}
 });
 discardButton.addEventListener("click",async()=>{
  if(busy||!current?.draftId||!window.confirm("\xBFDescartar este borrador? Las decisiones confirmadas se conservan."))return;
  busy=true;discardButton.disabled=true;evaluate();
  try{await draftRequest("/discard",{id:current.draftId,confirmed:true});invalidate();close();}
  catch(error){feedback.textContent=error.message;}
  finally{busy=false;discardButton.disabled=false;evaluate();}
 });
